Use Welford update to avoid catastrophic cancellation and overflow of naive sum of squares.
import numpy as np
class Welford:
    def __init__(self):
        self.n=0
        self.mean=0.0
        self.M2=0.0
    def update(self, x):
        self.n+=1
        d=x-self.mean
        self.mean+=d/self.n
        self.M2+=d*(x-self.mean)
    @property
    def var(self):
        return self.M2/(self.n-1) if self.n>1 else float('nan')
