Chunk queries and use float32 with numba to avoid full N by N matrix materialization.
import numpy as np
from numba import njit
@njit
def chunk_dist(A, B):
    n, m, d = A.shape[0], B.shape[0], A.shape[1]
    out = np.empty((n, m), dtype=np.float32)
    for i in range(n):
        for j in range(m):
            s = 0.0
            for k in range(d):
                v = A[i,k]-B[j,k]
                s += v*v
            out[i,j] = np.sqrt(s)
    return out
