import asyncio, random
from typing import Awaitable, Callable
async def call_with_retry(fn: Callable[[], Awaitable[str]], max_retries: int = 5, base: float = 1.0, timeout: float = 30.0) -> str:
    for attempt in range(max_retries + 1):
        try:
            return await asyncio.wait_for(fn(), timeout=timeout)
        except Exception as e:
            retryable = 'rate' in str(e).lower() or 'timeout' in str(e).lower() or '500' in str(e)
            if attempt == max_retries or not retryable:
                raise
            delay = base * (2 ** attempt) + random.uniform(0, 0.5)
            await asyncio.sleep(min(delay, 30))
    raise RuntimeError('unreachable')
