from typing import Any, Iterator
def flatten(nested: Any) -> Iterator[Any]:
    stack = [nested]
    while stack:
        cur = stack.pop()
        if isinstance(cur, (list, tuple)):
            for x in reversed(cur):
                stack.append(x)
        elif isinstance(cur, (str, bytes)):
            yield cur
        elif hasattr(cur, '__iter__'):
            yield cur
        else:
            yield cur
