from typing import Callable
class Container:
    def __init__(self):
        self._reg = {}
        self._single = {}
        self._stack = []
    def register(self, name: str, factory: Callable, singleton: bool = False):
        self._reg[name] = (factory, singleton)
    def resolve(self, name: str):
        if name in self._single:
            return self._single[name]
        if name in self._stack:
            raise RuntimeError(f'circular: {self._stack+[name]}')
        factory, single = self._reg[name]
        self._stack.append(name)
        try:
            obj = factory(self)
        finally:
            self._stack.pop()
        if single:
            self._single[name] = obj
        return obj
c = Container()
