Protocols enable structural subtyping (static duck typing) without requiring inheritance from a shared base class, allowing plugins to remain decoupled.

```python
from typing import Protocol, runtime_checkable
import importlib.metadata

@runtime_checkable
class ModelEmbeddingPlugin(Protocol):
    plugin_name: str
    dimension: int

    def embed_texts(self, texts: list[str]) -> list[list[float]]:
        ...

    def health_check(self) -> bool:
        ...

class PluginRegistry:
    def __init__(self, group_name: str = "ai.plugins.embeddings"):
        self.group_name = group_name
        self._plugins: dict[str, ModelEmbeddingPlugin] = {}

    def load_plugins(self):
        # Discover entrypoints registered in pyproject.toml
        entry_points = importlib.metadata.entry_points(group=self.group_name)
        for ep in entry_points:
            cls = ep.load()
            instance = cls()
            if isinstance(instance, ModelEmbeddingPlugin):
                self._plugins[instance.plugin_name] = instance
            else:
                raise TypeError(f"Plugin {ep.name} does not satisfy ModelEmbeddingPlugin protocol")

    def get_plugin(self, name: str) -> ModelEmbeddingPlugin:
        return self._plugins[name]
