Load testing streaming LLM endpoints requires measuring two distinct SLAs: Time-To-First-Token (TTFT) for initial responsiveness, and Inter-Token Latency (ITL) for generation smoothness.

```python
import time
from locust import HttpUser, task, between, events

class LLMStreamingUser(HttpUser):
    wait_time = between(1, 3)

    @task
    def stream_completion(self):
        start_time = time.perf_counter()
        ttft = None
        token_count = 0
        last_token_time = start_time
        itl_list = []

        payload = {
            "model": "qwen-4b-instruct",
            "messages": [{"role": "user", "content": "Explain vector indexing in 100 words."}],
            "stream": True
        }

        with self.client.post("/v1/chat/completions", json=payload, stream=True, catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"HTTP {resp.status_code}")
                return

            for line in resp.iter_lines():
                if not line:
                    continue
                now = time.perf_counter()
                if ttft is None:
                    ttft = (now - start_time) * 1000 # ms
                else:
                    itl_list.append((now - last_token_time) * 1000)
                last_token_time = now
                token_count += 1

            total_duration = time.perf_counter() - start_time
            avg_itl = sum(itl_list) / max(1, len(itl_list))

            # SLA Assertions: TTFT < 300ms, Avg ITL < 40ms (25 tokens/sec)
            if ttft and ttft > 300:
                resp.failure(f"TTFT SLA breached: {ttft:.1f}ms > 300ms")
            elif avg_itl > 40:
                resp.failure(f"ITL SLA breached: {avg_itl:.1f}ms > 40ms")
            else:
                resp.success()
