Network timeouts frequently prompt clients to retry POST requests. Without idempotency handling, retried requests create duplicate charges or redundant database mutations.

```python
import json
from fastapi import FastAPI, Request, HTTPException, Response
import redis.asyncio as aioredis

app = FastAPI()
redis_client = aioredis.from_url("redis://localhost:6379", decode_responses=True)

@app.middleware("http")
async def idempotency_middleware(request: Request, call_next):
    if request.method != "POST":
        return await call_next(request)

    idempotency_key = request.headers.get("Idempotency-Key")
    if not idempotency_key:
        return await call_next(request)

    redis_key = f"idempotency:{idempotency_key}"

    # 1. Check if response is already cached
    cached = await redis_client.get(redis_key)
    if cached:
        payload = json.loads(cached)
        return Response(
            content=payload["body"],
            status_code=payload["status_code"],
            media_type="application/json",
            headers={"X-Cache": "HIT-IDEMPOTENCY"}
        )

    # 2. Acquire in-flight lock to prevent concurrent duplicate execution
    lock_acquired = await redis_client.set(f"lock:{redis_key}", "1", nx=True, ex=30)
    if not lock_acquired:
        raise HTTPException(status_code=409, detail="Concurrent request with identical idempotency key in progress.")

    try:
        response = await call_next(request)
        # Cache response body for 24 hours
        body = [section async for section in response.body_iterator]
        full_body = b"".join(body).decode()

        await redis_client.setex(
            redis_key,
            86400,
            json.dumps({"status_code": response.status_code, "body": full_body})
        )
        return Response(content=full_body, status_code=response.status_code, media_type="application/json")
    finally:
        await redis_client.delete(f"lock:{redis_key}")
```

Here is a complete, self-contained Python JWT validation module and its full `pytest` test suite using standard library cryptography.

```python
import base64
import hashlib
import hmac
import json
import time
from typing import Any, Dict, Optional
import pytest


class JWTError(Exception):
    """Base exception for JWT verification failures."""
    pass


class TokenExpiredError(JWTError):
    pass


class InvalidSignatureError(JWTError):
    pass


def b64_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("utf-8").rstrip("=")


def b64_decode(data: str) -> bytes:
    padding = "=" * ((4 - len(data) % 4) % 4)
    return base64.urlsafe_b64decode(data + padding)


def create_token(payload: Dict[str, Any], secret_key: str) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    h_bytes = b64_encode(json.dumps(header).encode("utf-8"))
    p_bytes = b64_encode(json.dumps(payload).encode("utf-8"))
    signing_input = f"{h_bytes}.{p_bytes}".encode("utf-8")
    sig = hmac.new(secret_key.encode("utf-8"), signing_input, hashlib.sha256).digest()
    return f"{h_bytes}.{p_bytes}.{b64_encode(sig)}"


def verify_token(token: str, secret_key: str, leeway: float = 0.0) -> Dict[str, Any]:
    parts = token.strip().split(".")
    if len(parts) != 3:
        raise JWTError("Malformed token structure: must contain exactly 3 segments.")

    h_str, p_str, sig_str = parts
    signing_input = f"{h_str}.{p_str}".encode("utf-8")
    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, hashlib.sha256).digest()

    try:
        actual_sig = b64_decode(sig_str)
    except Exception as e:
        raise InvalidSignatureError("Invalid base64 signature encoding") from e

    if not hmac.compare_digest(expected_sig, actual_sig):
        raise InvalidSignatureError("Signature mismatch: token has been tampered with or key is invalid.")

    try:
        payload = json.loads(b64_decode(p_str).decode("utf-8"))
    except Exception as e:
        raise JWTError("Failed to decode token payload JSON") from e

    now = time.time()
    if "exp" in payload and now > (payload["exp"] + leeway):
        raise TokenExpiredError(f"Token expired at {payload['exp']}, current time {now}")

    if "nbf" in payload and now < (payload["nbf"] - leeway):
        raise JWTError(f"Token not valid before {payload['nbf']}, current time {now}")

    return payload


def extract_bearer_token(auth_header: Optional[str]) -> str:
    if not auth_header:
        raise JWTError("Missing Authorization header")
    parts = auth_header.strip().split(" ")
    if len(parts) != 2 or parts[0].lower() != "bearer":
        raise JWTError("Invalid Authorization header format: must be 'Bearer <token>'")
    return parts[1]


SECRET = "super-secret-ml-inference-signing-key-12345"


def test_valid_token_verification():
    payload = {"sub": "user_42", "role": "ml_engineer", "exp": time.time() + 3600}
    token = create_token(payload, SECRET)
    decoded = verify_token(token, SECRET)
    assert decoded["sub"] == "user_42"
    assert decoded["role"] == "ml_engineer"


def test_signature_tampering_rejection():
    payload = {"sub": "user_42", "role": "ml_engineer", "exp": time.time() + 3600}
    token = create_token(payload, SECRET)
    parts = token.split(".")
    tampered_payload = b64_encode(json.dumps({"sub": "user_42", "role": "admin"}).encode("utf-8"))
    tampered_token = f"{parts[0]}.{tampered_payload}.{parts[2]}"

    with pytest.raises(InvalidSignatureError, match="Signature mismatch"):
        verify_token(tampered_token, SECRET)


def test_expired_token_rejection():
    past_time = time.time() - 100
    token = create_token({"sub": "user_42", "exp": past_time}, SECRET)
    with pytest.raises(TokenExpiredError, match="Token expired"):
        verify_token(token, SECRET)


def test_nbf_future_rejection():
    future_time = time.time() + 500
    token = create_token({"sub": "user_42", "nbf": future_time}, SECRET)
    with pytest.raises(JWTError, match="Token not valid before"):
        verify_token(token, SECRET)


@pytest.mark.parametrize(
    "header_value, should_succeed, expected_error",
    [
        ("Bearer valid_token_string", True, None),
        ("bearer valid_token_string", True, None),
        ("", False, "Missing Authorization header"),
        (None, False, "Missing Authorization header"),
        ("Basic dXNlcjpwYXNz", False, "must be 'Bearer <token>'"),
        ("BearerTokenWithoutSpace", False, "must be 'Bearer <token>'"),
    ],
)
def test_extract_bearer_token(header_value, should_succeed, expected_error):
    if should_succeed:
        assert extract_bearer_token(header_value) == "valid_token_string"
    else:
        with pytest.raises(JWTError, match=expected_error):
            extract_bearer_token(header_value)
```

