Here is the complete citation alignment verification engine and its full `pytest` suite.

```python
from dataclasses import dataclass
from typing import List, Optional
import pytest


@dataclass(frozen=True)
class Citation:
    source_doc_id: str
    quote: str
    start_char: int
    end_char: int


@dataclass(frozen=True)
class VerificationResult:
    is_valid: bool
    citation: Citation
    error_reason: Optional[str] = None


class CitationVerifier:
    """Verifies that generated citations precisely match raw source document spans."""

    def __init__(self, documents: dict[str, str]) -> None:
        self.documents = documents

    def verify(self, citation: Citation) -> VerificationResult:
        doc = self.documents.get(citation.source_doc_id)
        if doc is None:
            return VerificationResult(
                is_valid=False,
                citation=citation,
                error_reason=f"Document ID '{citation.source_doc_id}' not found in corpus.",
            )

        if citation.start_char < 0 or citation.end_char > len(doc) or citation.start_char >= citation.end_char:
            return VerificationResult(
                is_valid=False,
                citation=citation,
                error_reason=f"Invalid span bounds: [{citation.start_char}:{citation.end_char}] for doc len {len(doc)}.",
            )

        extracted_text = doc[citation.start_char : citation.end_char]
        if extracted_text != citation.quote:
            return VerificationResult(
                is_valid=False,
                citation=citation,
                error_reason=f"Span mismatch. Expected '{citation.quote}', found '{extracted_text}'.",
            )

        return VerificationResult(is_valid=True, citation=citation)


@pytest.fixture
def sample_corpus() -> dict[str, str]:
    return {
        "doc_kv": "PagedAttention partitions the KV-cache into fixed-size blocks to avoid memory fragmentation.",
        "doc_quant": "AWQ protects the top 1% salient weight channels to maintain perplexity under 4-bit quantization.",
    }


@pytest.fixture
def verifier(sample_corpus: dict[str, str]) -> CitationVerifier:
