    assert result.error_reason is None


def test_missing_document_id(verifier: CitationVerifier):
    citation = Citation(
        source_doc_id="non_existent_doc",
        quote="any text",
        start_char=0,
        end_char=8,
    )
    result = verifier.verify(citation)
    assert result.is_valid is False
    assert "not found in corpus" in result.error_reason


@pytest.mark.parametrize(
    "start, end, reason_substr",
    [
        (-5, 10, "Invalid span bounds"),
        (10, 5, "Invalid span bounds"),
        (0, 500, "Invalid span bounds"),
