import pytest


def repair_and_parse_json(raw_text: str) -> Dict[str, Any]:
    """Extracts and cleanses JSON object from conversational LLM responses."""
    if not raw_text or not raw_text.strip():
        raise ValueError("Empty input string cannot be parsed as JSON.")

    text = raw_text.strip()

    fence_match = re.search(r'(?:`{3})(?:json)?\s*([\s\S]*?)(?:`{3})', text)
    if fence_match:
        text = fence_match.group(1).strip()

    start_bracket = text.find('{')
    start_square = text.find('[')

    if start_bracket == -1 and start_square == -1:
        raise ValueError(f"No JSON object or array delimiter found in response: '{text[:50]}...'")

    if start_bracket != -1 and (start_square == -1 or start_bracket < start_square):
        start_idx = start_bracket
        end_idx = text.rfind('}')
    else:
        start_idx = start_square
        end_idx = text.rfind(']')

    if end_idx == -1 or end_idx < start_idx:
        raise ValueError("Unmatched JSON opening bracket in response.")

    json_snippet = text[start_idx : end_idx + 1]
    json_snippet = re.sub(r',\s*([}\]])', r'\1', json_snippet)

    try:
        return json.loads(json_snippet)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON after cleansing: {exc.msg}") from exc


def test_clean_json_parsing():
    raw = '{"name": "classifier", "accuracy": 0.94}'
    result = repair_and_parse_json(raw)
    assert result == {"name": "classifier", "accuracy": 0.94}


def test_markdown_fence_stripping():
    fence = chr(96) * 3
    raw = f"""Here is the requested output:
{fence}json
{{
    "embedding_model": "text-embedding-3-small",
    "dimensions": 1536
}}
{fence}
Let me know if you need changes."""
    result = repair_and_parse_json(raw)
    assert result["embedding_model"] == "text-embedding-3-small"
    assert result["dimensions"] == 1536


def test_trailing_comma_repair():
    raw = '{"items": ["apple", "banana",], "count": 2,}'
    result = repair_and_parse_json(raw)
    assert result["items"] == ["apple", "banana"]
    assert result["count"] == 2


def test_nested_trailing_commas():
    raw = """{
        "config": {
            "timeout": 30,
            "retries": 3,
        },
        "tags": ["prod", "v2",],
    }"""
    result = repair_and_parse_json(raw)
    assert result["config"]["timeout"] == 30
    assert result["tags"] == ["prod", "v2"]


@pytest.mark.parametrize(
    "malformed_input, expected_err",
    [
        ("", "Empty input string"),
        ("   ", "Empty input string"),
        ("The model answered: None", "No JSON object or array delimiter"),
        ("{\"key\": \"unclosed", "Unmatched JSON opening bracket"),
    ],
)
def test_malformed_inputs_raise_value_error(malformed_input: str, expected_err: str):
    with pytest.raises(ValueError, match=expected_err):
        repair_and_parse_json(malformed_input)
