Here is the complete metrics aggregator implementation and its `pytest` test suite.

```python
import math
from typing import Dict, List, Optional
import pytest


class LatencyAggregator:
    """Calculates latency percentiles over recorded inference requests."""

    def __init__(self) -> None:
        self.samples: List[float] = []

    def record(self, latency_ms: float) -> None:
        if latency_ms < 0:
            raise ValueError("Latency must be non-negative.")
        self.samples.append(float(latency_ms))

    def count(self) -> int:
        return len(self.samples)

    def percentile(self, p: float) -> float:
        if not (0.0 <= p <= 100.0):
            raise ValueError("Percentile p must be between 0 and 100.")
        if not self.samples:
            raise ValueError("Cannot calculate percentiles on an empty dataset.")

        sorted_samples = sorted(self.samples)
        if len(sorted_samples) == 1:
            return sorted_samples[0]

        # Linear interpolation percentile
        k = (len(sorted_samples) - 1) * (p / 100.0)
        f = math.floor(k)
        c = math.ceil(k)
        if f == c:
            return sorted_samples[int(k)]
        d0 = sorted_samples[int(f)] * (c - k)
        d1 = sorted_samples[int(c)] * (k - f)
        return d0 + d1

    def summary(self) -> Dict[str, float]:
        if not self.samples:
            return {"count": 0, "p50": 0.0, "p90": 0.0, "p99": 0.0, "max": 0.0}

        return {
            "count": float(self.count()),
            "p50": round(self.percentile(50.0), 2),
            "p90": round(self.percentile(90.0), 2),
            "p99": round(self.percentile(99.0), 2),
            "max": round(max(self.samples), 2),
        }


@pytest.fixture
def aggregator() -> LatencyAggregator:
    return LatencyAggregator()


def test_empty_aggregator_summary(aggregator: LatencyAggregator):
    summary = aggregator.summary()
    assert summary["count"] == 0
    assert summary["p50"] == 0.0


def test_single_sample_percentiles(aggregator: LatencyAggregator):
    aggregator.record(25.4)
    summary = aggregator.summary()
    assert summary["count"] == 1
    assert summary["p50"] == 25.4
    assert summary["p99"] == 25.4
    assert summary["max"] == 25.4


def test_known_distribution_quantiles(aggregator: LatencyAggregator):
    # 100 samples from 1 to 100 ms
    for i in range(1, 101):
        aggregator.record(float(i))

    summary = aggregator.summary()
    assert summary["count"] == 100
    assert summary["p50"] == 50.5
    assert summary["p90"] == 90.1
    assert summary["p99"] == 99.01
    assert summary["max"] == 100.0


def test_negative_latency_raises_value_error(aggregator: LatencyAggregator):
    with pytest.raises(ValueError, match="non-negative"):
        aggregator.record(-1.5)
```

