Here is an implementation of a structured log sanitizer and its complete `pytest` test suite.

```python
import re
from typing import Any, Dict, List, Union
import pytest

PATTERNS = [
    # OpenAI / Anthropic API keys (sk-..., sk-proj-...)
    (re.compile(r'sk-[a-zA-Z0-9\-_]{20,}', re.IGNORECASE), "[REDACTED_API_KEY]"),
    # AWS Access Key ID (AKIA...)
    (re.compile(r'AKIA[0-9A-Z]{16}'), "[REDACTED_AWS_KEY]"),
    # Bearer tokens
    (re.compile(r'Bearer\s+[a-zA-Z0-9\-_.]+', re.IGNORECASE), "Bearer [REDACTED_TOKEN]"),
]


def sanitize_value(val: Any) -> Any:
    """Recursively redacts sensitive patterns in strings, lists, and dictionaries."""
    if isinstance(val, str):
        result = val
        for pattern, replacement in PATTERNS:
            result = pattern.sub(replacement, result)
        return result
    elif isinstance(val, dict):
        return {k: sanitize_value(v) for k, v in val.items()}
    elif isinstance(val, list):
        return [sanitize_value(item) for item in val]
    return val


def sanitize_log_event(event: Dict[str, Any]) -> Dict[str, Any]:
    sensitive_keys = {"password", "secret", "token", "authorization", "api_key"}
    sanitized = {}
    for k, v in event.items():
        if k.lower() in sensitive_keys and isinstance(v, str):
            sanitized[k] = "[REDACTED]"
        elif isinstance(v, dict):
            sanitized[k] = sanitize_log_event(v)
        elif isinstance(v, list):
            sanitized[k] = [
                sanitize_log_event(item) if isinstance(item, dict) else sanitize_value(item)
                for item in v
            ]
        else:
            sanitized[k] = sanitize_value(v)
    return sanitized


def test_openai_key_masking():
    event = {"msg": "Calling model with key sk-proj-1234567890abcdef1234567890abcdef"}
    clean = sanitize_log_event(event)
    assert "sk-proj" not in clean["msg"]
    assert "[REDACTED_API_KEY]" in clean["msg"]


def test_aws_access_key_masking():
    event = {"error": "AccessDenied with credential AKIAIOSFODNN7EXAMPLE for s3://bucket"}
    clean = sanitize_log_event(event)
    assert "AKIAIOSFODNN7EXAMPLE" not in clean["error"]
    assert "[REDACTED_AWS_KEY]" in clean["error"]


def test_bearer_token_header_masking():
    event = {"headers": {"Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.dummy"}}
    clean = sanitize_log_event(event)
    assert clean["headers"]["Authorization"] == "[REDACTED]"


def test_nested_dictionary_and_list_sanitization():
    event = {
        "pipeline": "ingestion",
        "steps": [
            {"cmd": "curl -H 'Authorization: Bearer my_secret_token_123' http://api"},
            {"retries": 3},
        ],
    }
    clean = sanitize_log_event(event)
    assert "my_secret_token_123" not in clean["steps"][0]["cmd"]
    assert "Bearer [REDACTED_TOKEN]" in clean["steps"][0]["cmd"]
    assert clean["steps"][1]["retries"] == 3
