```python
from dataclasses import dataclass
from typing import Any, Dict, List, Optional
import pytest

ALLOWED_MODELS = {"qwen3-4b-instruct", "qwen3-7b-instruct", "qwen3-14b-instruct"}


@dataclass(frozen=True)
class CompletionRequest:
    prompt: str
    model: str
    temperature: float
    max_tokens: int


def validate_completion_request(payload: Dict[str, Any]) -> CompletionRequest:
    """Validates LLM inference request dictionary and returns sanitized dataclass."""
    if not isinstance(payload, dict):
        raise ValueError("Payload must be a dictionary.")

    prompt = payload.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("Field 'prompt' must be a non-empty string.")
    if len(prompt) > 32000:
        raise ValueError("Field 'prompt' exceeds maximum permitted length of 32,000 characters.")

    model = payload.get("model", "qwen3-4b-instruct")
    if model not in ALLOWED_MODELS:
        raise ValueError(f"Model '{model}' is not supported. Allowed: {sorted(ALLOWED_MODELS)}")

    temp = payload.get("temperature", 0.7)
    if not isinstance(temp, (int, float)) or not (0.0 <= temp <= 2.0):
        raise ValueError("Field 'temperature' must be a float between 0.0 and 2.0.")

    max_tokens = payload.get("max_tokens", 512)
    if not isinstance(max_tokens, int) or max_tokens <= 0 or max_tokens > 4096:
        raise ValueError("Field 'max_tokens' must be an integer between 1 and 4096.")

    return CompletionRequest(
        prompt=prompt.strip(),
        model=model,
        temperature=float(temp),
        max_tokens=max_tokens,
    )


def test_valid_request():
    payload = {"prompt": "Explain LoRA rank selection.", "model": "qwen3-4b-instruct", "temperature": 0.2, "max_tokens": 256}
    req = validate_completion_request(payload)
    assert req.prompt == "Explain LoRA rank selection."
    assert req.model == "qwen3-4b-instruct"
    assert req.temperature == 0.2
    assert req.max_tokens == 256


@pytest.mark.parametrize(
    "invalid_payload, err_match",
    [
        ({"prompt": "", "model": "qwen3-4b-instruct"}, "non-empty string"),
        ({"prompt": "hi", "model": "unsupported-gpt"}, "not supported"),
        ({"prompt": "hi", "temperature": -0.1}, "between 0.0 and 2.0"),
        ({"prompt": "hi", "temperature": 2.5}, "between 0.0 and 2.0"),
        ({"prompt": "hi", "max_tokens": 0}, "between 1 and 4096"),
        ({"prompt": "hi", "max_tokens": 5000}, "between 1 and 4096"),
    ],
)
def test_invalid_requests_raise_value_error(invalid_payload: dict, err_match: str):
