        self.request_count: Dict[str, int] = {}  # model -> count
        self.token_count: Dict[str, int] = {}    # model -> tokens
        self.latency_buckets = [0.05, 0.1, 0.25, 0.5, 1.0, 2.5, 5.0]
        self.bucket_counts: Dict[str, Dict[float, int]] = {}

