        self.token_count[model] = self.token_count.get(model, 0) + tokens_generated

        if model not in self.bucket_counts:
            self.bucket_counts[model] = {b: 0 for b in self.latency_buckets}

        for b in self.latency_buckets:
            if duration_seconds <= b:
                self.bucket_counts[model][b] += 1

    def scrape_text(self) -> str:
        lines = [
            "# HELP llm_requests_total Total number of inference requests.",
            "# TYPE llm_requests_total counter",
        ]
        for model, cnt in self.request_count.items():
            lines.append(f'llm_requests_total{{model="{model}"}} {cnt}')

        lines.extend([
            "# HELP llm_tokens_generated_total Total generated tokens.",
            "# TYPE llm_tokens_generated_total counter",
        ])
        for model, tokens in self.token_count.items():
            lines.append(f'llm_tokens_generated_total{{model="{model}"}} {tokens}')

        lines.extend([
            "# HELP llm_request_duration_seconds Latency histogram.",
            "# TYPE llm_request_duration_seconds histogram",
        ])
        for model, buckets in self.bucket_counts.items():
            for b in self.latency_buckets:
                lines.append(f'llm_request_duration_seconds_bucket{{model="{model}",le="{b}"}} {buckets[b]}')
            lines.append(f'llm_request_duration_seconds_bucket{{model="{model}",le="+Inf"}} {self.request_count[model]}')

