```python
def parse_json(json_str):
    stack = []
    result = {}
    current_key = ''
    is_value = False
    is_string = False
    escape = False

    for char in json_str:
        if char == '{' and not is_string:
            stack.append(result)
            result[current_key] = {}
            result = result[current_key]
            current_key = ''
        elif char == '}' and not is_string:
            result = stack.pop()
        elif char == '[' and not is_string:
            stack.append(result)
            result[current_key] = []
            result = result[current_key]
            current_key = ''
        elif char == ']' and not is_string:
            result = stack.pop()
        elif char == ':' and not is_string:
            is_value = True
            is_string = False
        elif char == ',' and not is_string:
            is_value = False
            is_string = False
            current_key = ''
        elif char == '"' and not escape:
            is_string = not is_string
            if not is_string and is_value:
                result[current_key] = current_value
                current_value = ''
        elif char == '\\' and not escape:
            escape = True
        elif escape:
            if char == 'n':
                char = '\n'
            elif char == 't':
                char = '\t'
            escape = False

        if is_string and is_value:
            current_value += char
        elif not is_string and not is_value and char.isalnum():
            current_key += char

    return result
```

