import json

class Book:
    def __init__(self, title, isbn):
        self.title = title
        self.isbn = isbn

class BookLibrary:
    def __init__(self):
        self.books = []
        self.title_index = {}
        self.isbn_index = {}

    def add_book(self, title, isbn):
        # Check if the book already exists
        if isbn in self.isbn_index:
            raise ValueError("Book with the same ISBN already exists.")
        if title in self.title_index:
            for book in self.title_index[title]:
                if book.isbn == isbn:
                    raise ValueError("Book with the same title and ISBN already exists.")

        book = Book(title, isbn)
        self.books.append(book)

        # Update the title index
        if title in self.title_index:
            self.title_index[title].append(book)
        else:
            self.title_index[title] = [book]

        # Update the ISBN index
        self.isbn_index[isbn] = book

    def get_title_by_isbn(self, isbn):
        if isbn in self.isbn_index:
            return self.isbn_index[isbn].title
        else:
            raise ValueError("Book with the given ISBN not found.")

    def get_isbn_by_title(self, title):
        if title in self.title_index:
            books_with_title = self.title_index[title]
            isbns = [book.isbn for book in books_with_title]
            return isbns
        else:
            raise ValueError("Book with the given title not found.")

    def search_by_partial_title(self, keyword):
        keyword = keyword.lower()
        results = []

        for title in self.title_index:
            if keyword in title.lower():
                results.extend(self.get_isbn_by_title(title))

        return results

    def search_by_isbn_prefix(self, prefix):
        prefix = prefix.lower()
        results = []

        for isbn in self.isbn_index:
            if isbn.lower().startswith(prefix):
                results.append(isbn)

        return results

    def delete_by_title(self, title):
        if title in self.title_index:
            books_to_delete = self.title_index[title]
            for book in books_to_delete:
                self.books.remove(book)
                del self.isbn_index[book.isbn]

            del self.title_index[title]
        else:
            raise ValueError("Book with the given title not found.")

    def delete_by_isbn(self, isbn):
        if isbn in self.isbn_index:
            book_to_delete = self.isbn_index[isbn]
            self.books.remove(book_to_delete)
            del self.isbn_index[isbn]

            # Update the title index
            self.title_index[book_to_delete.title].remove(book_to_delete)
            if len(self.title_index[book_to_delete.title]) == 0:
                del self.title_index[book_to_delete.title]
        else:
            raise ValueError("Book with the given ISBN not found.")

    def load_library(self, filename):
        with open(filename, "r") as file:
            data = json.load(file)

        self.books = []
        self.title_index = {}
        self.isbn_index = {}

        for book_data in data:
            title = book_data["title"]
            isbn = book_data["isbn"]
            book = Book(title, isbn)
            self.add_book(title, isbn)

    def save_library(self, filename):
        data = []
        for book in self.books:
            data.append({"title": book.title, "isbn": book.isbn})

        with open(filename, "w") as file:
            json.dump(data, file, indent=4)
