The `is_balanced` method should determine whether the constructed BST is height balanced or not. A BST is height balanced if the heights of its left and right subtrees differ by at most 1. Implement the `is_balanced` method efficiently to achieve a time complexity of O(n).

Here is the code to construct a balanced BST with the given elements:

```python
class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        if self.root is None:
            self.root = TreeNode(val)
        else:
            current = self.root
            while current is not None:
                if val < current.val:
                    if current.left is None:
                        current.left = TreeNode(val)
                        break
                    else:
                        current = current.left
                else:
                    if current.right is None:
                        current.right = TreeNode(val)
                        break
                    else:
                        current = current.right

    def is_balanced(self) -> bool:
        """
        Returns True if the BST is height balanced, False otherwise.
        """
        def get_height(node):
            if node is None:
                return 0
            return max(get_height(node.left), get_height(node.right)) + 1

        def is_balanced_helper(node):
            if node is None:
                return True
            left_height = get_height(node.left)
            right_height = get_height(node.right)
            if abs(left_height - right_height) > 1:
                return False
            return is_balanced_helper(node.left) and is_balanced_helper(node.right)

        return is_balanced_helper(self.root)

# Construct the balanced BST
bst = BST()
elements = [11, 18, 14, 6, 7, 4, 23, 15, 8, 10]
for element in elements:
    bst.insert(element)

# Check if the BST is height balanced
print(bst.is_balanced())  # Output: True
```

The `is_balanced` method uses a helper function `get_height` to calculate the height of each subtree. Then, it recursively checks if the heights of the left and right subtrees differ by at most 1 for each node in the BST.

The output of the above code is `True`, indicating that the constructed BST is height balanced.

Here is an implementation of a doubly linked list class in Python with the required functionalities:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node
        self.size += 1

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.tail is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def insert_after(self, node, data):
        if node is None:
            raise ValueError("Node is None.")
        new_node = Node(data)
        new_node.prev = node
        new_node.next = node.next
        if node.next is not None:
            node.next.prev = new_node
        node.next = new_node
        if node == self.tail:
            self.tail = new_node
        self.size += 1

    def delete(self, node):
        if node is None:
            raise ValueError("Node is None.")
        if node.prev is not None:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next is not None:
            node.next.prev = node.prev
        else:
            self.tail = node.prev
        self.size -= 1

    def delete_all(self, value):
        current = self.head
        while current is not None:
            if current.data == value:
                if current.prev is not None:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                if current.next is not None:
                    current.next.prev = current.prev
                else:
                    self.tail = current.prev
                self.size -= 1
            current = current.next

    def get_size(self):
        return self.size

    def contains(self, value):
        current = self.head
        while current is not None:
            if current.data == value:
                return True
            current = current.next
        return False

    def reverse(self):
        current = self.head
        while current is not None:
            temp = current.next
            current.next = current.prev
            current.prev = temp
            if temp is None:
                self.tail = self.head
                self.head = current
            current = temp

    def print_list(self):
        current = self.head
        while current is not None:
            print(current.data, end=" ")
            current = current.next
        print()
