Here is an updated implementation of the stack data structure in Python, including the additional functionalities:

```python
class Stack:
    def __init__(self):
        self.stack = []
        self.minimum = float('inf')
        self.maximum = float('-inf')
        self.total = 0
        self.counts = {}
        self.mode = None

    def push(self, value):
        self.stack.append(value)
        self.minimum = min(self.minimum, value)
        self.maximum = max(self.maximum, value)
        self.total += value
        self.counts[value] = self.counts.get(value, 0) + 1
        if self.mode is None or self.counts[value] > self.counts[self.mode]:
            self.mode = value

    def pop(self):
        if self.is_empty():
            return "Stack is empty"
        value = self.stack.pop()
        if value == self.minimum:
            self.minimum = min(self.stack) if self.stack else float('inf')
        if value == self.maximum:
            self.maximum = max(self.stack) if self.stack else float('-inf')
        self.total -= value
        self.counts[value] -= 1
        if self.counts[value] == 0:
            del self.counts[value]
            if value == self.mode:
                self.mode = max(self.counts, key=self.counts.get) if self.counts else None
        return value

    def peek(self):
        if self.is_empty():
            return "Stack is empty"
        return self.stack[-1]

    def is_empty(self):
        return len(self.stack) == 0

    def size(self):
        return len(self.stack)

    def get_minimum(self):
        if self.is_empty():
            return "Stack is empty"
        return self.minimum

    def get_maximum(self):
        if self.is_empty():
            return "Stack is empty"
        return self.maximum

    def get_average(self):
        if self.is_empty():
            return "Stack is empty"
        return self.total / len(self.stack)

    def get_median(self):
        if self.is_empty():
            return "Stack is empty"
        sorted_stack = sorted(self.stack)
        mid = len(sorted_stack) // 2
        if len(sorted_stack) % 2 == 0:
            return (sorted_stack[mid-1] + sorted_stack[mid]) / 2
        else:
            return sorted_stack[mid]

    def get_mode(self):
        if self.is_empty():
            return "Stack is empty"
        return self.mode
```

