import random

class BankAccount:
    def __init__(self):
        self._account_number = self._generate_account_number()
        self._balance = 0

    @property
    def account_number(self):
        return self._account_number

    @property
    def balance(self):
        return self._balance

    def _generate_account_number(self):
        return ''.join(random.choices('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ', k=10))

    def deposit(self, amount):
        if amount < 0:
            raise ValueError("Amount must be a non-negative number")
        self._balance += amount

    def withdraw(self, amount):
        if amount < 0:
            raise ValueError("Amount must be a non-negative number")
        if amount > self._balance:
            raise ValueError("Insufficient balance")
        self._balance -= amount

    def get_balance(self):
        return self._balance


class SavingsAccount(BankAccount):
    def __init__(self, interest_rate):
        super().__init__()
        self._interest_rate = self._validate_interest_rate(interest_rate)

    @property
    def interest_rate(self):
        return self._interest_rate

    def _validate_interest_rate(self, interest_rate):
        if interest_rate < 0 or interest_rate > 1:
            raise ValueError("Interest rate must be between 0 and 1")
        return interest_rate

    def calculate_interest(self):
        interest = round(self._balance * self._interest_rate, 2)
        self._balance += interest


class CheckingAccount(BankAccount):
    def __init__(self, transaction_limit):
        super().__init__()
        self._transaction_limit = self._validate_transaction_limit(transaction_limit)
        self._transaction_count = 0

    @property
    def transaction_limit(self):
        return self._transaction_limit

    @property
    def transaction_count(self):
        return self._transaction_count

    def _validate_transaction_limit(self, transaction_limit):
        if transaction_limit <= 0:
            raise ValueError("Transaction limit must be a positive integer")
        return transaction_limit

    def increment_transaction_count(self):
        self._transaction_count += 1

    def reset_transaction_count(self):
        self._transaction_count = 0

    def withdraw(self, amount):
        super().withdraw(amount)
        self.increment_transaction_count()
        if self._transaction_count > self._transaction_limit:
            self._balance += amount
            self.decrement_transaction_count()
            raise ValueError("Transaction limit exceeded")

    def decrement_transaction_count(self):
        self._transaction_count -= 1


