```python
class PascalTriangle:
    def __init__(self):
        self.triangle = []

    def generate_next_line(self, parent_line):
        if not self.is_valid_line(parent_line):
            raise ValueError("Invalid parent line")

        current_line = []
        for i in range(len(parent_line) + 1):
            if i == 0 or i == len(parent_line):
                current_line.append(1)
            else:
                current_line.append(parent_line[i-1] + parent_line[i])

        self.triangle.append(current_line)
        return current_line

    def is_valid_line(self, line):
        if len(line) < 2:
            return True

        for i in range(len(line) - 1):
            if line[i] > line[i+1]:
                return False

        return True

    def generate_triangle(self, num_lines):
        total_sum = 0
        for _ in range(num_lines):
            parent_line = self.triangle[-1] if self.triangle else [1]
            current_line = self.generate_next_line(parent_line)
            total_sum += sum(current_line)

        return total_sum, self.triangle
```

