import random

class Node:
    def __init__(self, value, color):
        self.value = value
        self.color = color
        self.children = []

    def add_child(self, child):
        self.children.append(child)

    def remove_child(self, child):
        self.children.remove(child)

    def is_leaf(self):
        return len(self.children) == 0

def generate_mulberry_tree(height):
    if height < 50:
        raise ValueError("Height must be at least 50")

    root = Node(random.randint(0, 100), random.choice(["red", "blue", "green", "yellow"]))
    generate_mulberry_tree_recursive(root, height - 1)
    return root

def generate_mulberry_tree_recursive(node, height):
    if height == 0:
        return

    num_children = random.randint(1, 5)
    for _ in range(num_children):
        child = Node(random.randint(0, 100), random.choice(["red", "blue", "green", "yellow"]))
        node.add_child(child)
        generate_mulberry_tree_recursive(child, height - 1)

def display_mulberry_tree(node, level=0):
    indent = "  " * level
    print(f"{indent}└── Value: {node.value}, Color: {node.color}")

    for child in node.children:
        display_mulberry_tree(child, level + 1)

def sum_values(node):
    total = node.value
    for child in node.children:
        total += sum_values(child)
    return total

def find_maximum(node):
    max_value = node.value
    for child in node.children:
        max_value = max(max_value, find_maximum(child))
    return max_value

def find_minimum(node):
    min_value = node.value
    for child in node.children:
        min_value = min(min_value, find_minimum(child))
    return min_value

def find_average(node):
    total, count = node.value, 1
    for child in node.children:
        child_total, child_count = find_average(child)
        total += child_total
        count += child_count
    return total, count

def search_value(node, target):
    if node.value == target:
        return [node]

    for child in node.children:
        result = search_value(child, target)
        if result:
            return [node] + result

    return []

def delete_node(node, target):
    if node.value == target:
        parent = find_parent(node)
        if parent:
            parent.remove_child(node)
        return True

    for child in node.children:
        if delete_node(child, target):
            return True

    return False

def find_parent(node, parent=None):
    if parent is None:
        parent = node
    for child in parent.children:
        if child == node:
            return parent
        result = find_parent(node, child)
        if result:
            return result
    return None

def swap_nodes(node1, node2):
    node1.value, node2.value = node2.value, node1.value
    node1.color, node2.color = node2.color, node1.color

def rotate_tree(node, levels, direction):
    if direction == "left":
        for _ in range(levels):
            node.children.append(node)
            node = node.children.pop(0)
    elif direction == "right":
        for _ in range(levels):
            node.children.insert(0, node)
            node = node.children.pop()

    for child in node.children:
        rotate_tree(child, levels, direction)
