import re
import datetime

class DateTimeConverter:
    def __init__(self):
        self.date_pattern = r'\d{1,2}[./-]\d{1,2}[./-]\d{2,4}'
        self.time_pattern = r'\d{1,2}:\d{2}(:\d{2})?( )?(am|pm)?'
        self.tz_pattern = r'([+-]\d{2}:\d{2})|(\b[A-Z]{2,5}\b)'

    def convert_to_iso8601(self, datetime_str, timezone_str):
        if not self.validate_input(datetime_str, timezone_str):
            return 'Invalid input format.'

        date_str, time_str = self.extract_date_time(datetime_str)
        timezone = self.extract_timezone(timezone_str)

        try:
            dt = datetime.datetime.strptime(date_str + ' ' + time_str, '%Y-%m-%d %H:%M:%S')
        except ValueError:
            return 'Invalid date or time format.'

        dt = self.adjust_for_leap_year(dt)
        dt = self.adjust_for_dst(dt, timezone)
        dt = self.adjust_for_timezone(dt, timezone)

        return dt.isoformat()

    def validate_input(self, datetime_str, timezone_str):
        if not re.match(self.date_pattern, datetime_str) or not re.match(self.time_pattern, datetime_str):
            return False

        if not re.match(self.tz_pattern, timezone_str):
            return False

        return True

    def extract_date_time(self, datetime_str):
        date_str = re.search(self.date_pattern, datetime_str).group()
        time_str = re.search(self.time_pattern, datetime_str).group()
        return date_str, time_str

    def extract_timezone(self, timezone_str):
        if re.match(r'[+-]\d{2}:\d{2}', timezone_str):
            return datetime.timezone(datetime.timedelta(hours=int(timezone_str[:3]), minutes=int(timezone_str[4:])))
        else:
            try:
                return datetime.timezone(datetime.timedelta(hours=int(timezone_str)))
            except ValueError:
                return datetime.timezone(datetime.timedelta(hours=0))

    def adjust_for_leap_year(self, dt):
        if dt.year % 4 == 0 and (dt.year % 100 != 0 or dt.year % 400 == 0):
            dt = dt.replace(day=29)
        return dt

    def adjust_for_dst(self, dt, timezone):
        if timezone.dst(dt) != datetime.timedelta(0):
            dt = dt - timezone.dst(dt)
        return dt

    def adjust_for_timezone(self, dt, timezone):
        dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(timezone)
        return dt
```

