import datetime

class DateConverter:
    def __init__(self, date_str):
        self.date_str = date_str
        self.date_obj = None
        self.weekday = None

    def validate_date(self):
        try:
            self.date_obj = datetime.datetime.strptime(self.date_str, "%d/%m/%Y")
        except ValueError:
            raise ValueError("Invalid date format. Please use dd/mm/yyyy format.")

    def get_weekday(self):
        if self.date_obj:
            self.weekday = self.date_obj.strftime("%A")

    def is_leap_year(self, year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def print_day(self):
        day, month, year = map(int, self.date_str.split('/'))

        if month < 1 or month > 12:
            raise ValueError("Invalid month. Please enter a value between 1 and 12.")
        if day < 1 or day > 31:
            raise ValueError("Invalid day. Please enter a value between 1 and 31.")

        if month in [4, 6, 9, 11] and day > 30:
            raise ValueError("Invalid day for the given month.")

        if month == 2:
            if self.is_leap_year(year):
                if day > 29:
                    raise ValueError("Invalid day for February in a leap year.")
            elif day > 28:
                raise ValueError("Invalid day for February in a non-leap year.")

        self.validate_date()
        self.get_weekday()
        print(f"The day for {self.date_str} is {self.weekday}.")

# Test case 1
