import math

class ComplexNumber:
    def __init__(self, real, imaginary):
        if not isinstance(real, (int, float)) or not isinstance(imaginary, (int, float)):
            raise ValueError("Real and imaginary parts must be numbers.")
        self.real = real
        self.imaginary = imaginary

    def get_real(self):
        return self.real

    def get_imaginary(self):
        return self.imaginary

    def add(self, other):
        if not isinstance(other, ComplexNumber):
            raise ValueError("The input must be a complex number.")
        return ComplexNumber(self.real + other.get_real(), self.imaginary + other.get_imaginary())

    def subtract(self, other):
        if not isinstance(other, ComplexNumber):
            raise ValueError("The input must be a complex number.")
        return ComplexNumber(self.real - other.get_real(), self.imaginary - other.get_imaginary())

    def multiply(self, other):
        if not isinstance(other, ComplexNumber):
            raise ValueError("The input must be a complex number.")
        real_part = self.real * other.get_real() - self.imaginary * other.get_imaginary()
        imaginary_part = self.real * other.get_imaginary() + self.imaginary * other.get_real()
        return ComplexNumber(real_part, imaginary_part)

    def divide(self, other):
        if not isinstance(other, ComplexNumber):
            raise ValueError("The input must be a complex number.")
        divisor = other.get_real()**2 + other.get_imaginary()**2
        if divisor == 0:
            raise ZeroDivisionError("Division by zero is not allowed.")
        real_part = (self.real * other.get_real() + self.imaginary * other.get_imaginary()) / divisor
        imaginary_part = (self.imaginary * other.get_real() - self.real * other.get_imaginary()) / divisor
        return ComplexNumber(real_part, imaginary_part)

    def modulus(self):
        return math.sqrt(self.real**2 + self.imaginary**2)

    def conjugate(self):
        return ComplexNumber(self.real, -self.imaginary)

    def is_equal(self, other):
        if not isinstance(other, ComplexNumber):
            raise ValueError("The input must be a complex number.")
        return self.real == other.get_real() and self.imaginary == other.get_imaginary()

    def is_zero(self):
        return self.real == 0 and self.imaginary == 0

    def __str__(self):
        return f"{self.real} + {self.imaginary}i"
```

