```python
class MinHeap:
    def __init__(self):
        self.heap = []

    def insert(self, item):
        self.heap.append(item)
        self._bubble_up(len(self.heap) - 1)

    def delete_min(self):
        if not self.heap:
            raise IndexError("Heap is empty")

        min_item = self.heap[0]
        last_item = self.heap.pop()
        if self.heap:
            self.heap[0] = last_item
            self._bubble_down(0)

        return min_item

    def search(self, item):
        for i in range(len(self.heap)):
            if self.heap[i] == item:
                return True
        return False

    def merge(self, other_heap):
        merged_heap = MinHeap()
        merged_heap.heap = self.heap + other_heap.heap
        merged_heap._build_heap()
        return merged_heap

    def _bubble_up(self, index):
        while index > 0:
            parent_index = (index - 1) // 2
            if self.heap[parent_index] > self.heap[index]:
                self.heap[parent_index], self.heap[index] = self.heap[index], self.heap[parent_index]
                index = parent_index
            else:
                break

    def _bubble_down(self, index):
        while True:
            left_child_index = 2 * index + 1
            right_child_index = 2 * index + 2
            smallest_child_index = index

            if left_child_index < len(self.heap) and self.heap[left_child_index] < self.heap[smallest_child_index]:
                smallest_child_index = left_child_index

            if right_child_index < len(self.heap) and self.heap[right_child_index] < self.heap[smallest_child_index]:
                smallest_child_index = right_child_index

            if smallest_child_index != index:
                self.heap[index], self.heap[smallest_child_index] = self.heap[smallest_child_index], self.heap[index]
                index = smallest_child_index
            else:
                break

    def _build_heap(self):
        for i in range(len(self.heap) // 2, -1, -1):
            self._bubble_down(i)
```

