import math

class Calculator:
    def add(self, num1, num2):
        self._validate_positive_integer(num1)
        self._validate_positive_integer(num2)
        return num1 + num2

    def subtract(self, num1, num2):
        self._validate_positive_integer(num1)
        self._validate_positive_integer(num2)
        return num1 - num2

    def multiply(self, num1, num2):
        self._validate_positive_integer(num1)
        self._validate_positive_integer(num2)
        return num1 * num2

    def divide(self, num1, num2):
        self._validate_positive_integer(num1)
        self._validate_positive_integer(num2)
        if num2 == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        return num1 / num2

    def square_root(self, num):
        self._validate_positive_integer(num)
        return math.sqrt(num)

    def factorial(self, num):
        self._validate_positive_integer(num)
        return math.factorial(num)

    def exponent(self, base, power):
        self._validate_positive_integer(base)
        self._validate_positive_integer(power)
        return base ** power

    def logarithm(self, number, base):
        self._validate_positive_integer(number)
        self._validate_positive_integer(base)
        if base <= 1:
            raise ValueError("Base must be greater than 1")
        return math.log(number, base)

    def absolute_value(self, num):
        if not isinstance(num, (int, float)):
            raise TypeError("Argument must be a number")
        return abs(num)

    def _validate_positive_integer(self, num):
        if not isinstance(num, int) or num <= 0:
            raise ValueError("Argument must be a positive integer")
