import random

class RandomGenerator:
    @staticmethod
    def generateRandomNumber(min, max):
        if min < 0 or max < 0:
            raise ValueError("Invalid input values. Min and max must be positive.")
        if min > max:
            raise ValueError("Invalid input values. Min must be less than or equal to max.")

        generated_number = random.randint(min, max)
        return generated_number

    @staticmethod
    def generateRandomNumberList(n, min, max):
        if min < 0 or max < 0 or n < 0:
            raise ValueError("Invalid input values. Min, max, and n must be positive.")
        if min > max:
            raise ValueError("Invalid input values. Min must be less than or equal to max.")

        random_numbers = []
        while len(random_numbers) < n:
            generated_number = random.randint(min, max)
            if generated_number not in random_numbers:
                random_numbers.append(generated_number)

        return random_numbers

    @staticmethod
    def calculateSum(numbers):
        if len(numbers) == 0:
            raise ValueError("Empty list. Please provide a non-empty list.")

        total_sum = 0
        for number in numbers:
            if not isinstance(number, (int, float)):
                raise ValueError("Non-numeric value found in the list.")
            total_sum += number

        return total_sum
