from typing import Dict, List, Tuple

class StudentMarks:
    def __init__(self):
        self.students = {}

    def add_student(self, name: str) -> None:
        self.students[name] = []

    def add_mark(self, name: str, subject: str, mark: int) -> None:
        if name not in self.students:
            raise Exception(f"Student {name} does not exist")
        self.students[name].append((subject, mark))

    def get_average_mark(self, name: str) -> float:
        if name not in self.students:
            raise Exception(f"Student {name} does not exist")
        marks = self.students[name]
        total_marks = sum([mark for _, mark in marks])
        return total_marks / len(marks)

    def get_highest_mark(self, subject: str) -> Tuple[str, int]:
        max_mark = -1
        max_student = None
        for name, marks in self.students.items():
            for subj, mark in marks:
                if subj == subject and mark > max_mark:
                    max_mark = mark
                    max_student = name
        if max_student is None:
            raise Exception(f"No student has marks for subject {subject}")
        return max_student, max_mark

    def get_subjects(self) -> List[str]:
        subjects = set()
        for marks in self.students.values():
            for subj, _ in marks:
                subjects.add(subj)
        return list(subjects)
