    if not isinstance(n, int) or n <= 1:
        return "Invalid input"

    # Check for base case where input is 1
    if n == 1:
        return "1 has no prime factors"

    def prime_factors_helper(n, factor):
        # Base case: n is a prime number
        if is_prime(n):
            return [n]

        # Base case: factor is greater than sqrt(n)
        if factor > int(n**0.5):
            return []

        # Recursive case: find prime factors
        if n % factor == 0:
            return [factor] + prime_factors_helper(n // factor, factor)
        else:
            return prime_factors_helper(n, factor + 1)

    factors = prime_factors_helper(n, 2)
    count = len(factors)
    return factors, count

