        self.operations = []
        self.variables = []
        self.params = []
        output_op = self.lazy_eval(inputs[0], self.construct_graph, *inputs[1:])
        return output_op.output
        
    def lazy_eval(self, x, fn, *args):
        def lazy_fn():
            y = fn(*args)
            return y
            
        op = Operation(lazy_fn, [x])
        self.add_operation(op)
        return op
        
    def construct_graph(self, *args):
        raise NotImplementedError
        
    def backward(self, y_grad=None):
        if y_grad is None:
            y_grad = np.ones_like(self.operations[-1].output)
        
        self.operations[-1].grads = y_grad
        for op in reversed(self.operations):
            op.backward()
            
    def zero_grad(self):
        for variable in self.variables:
            variable.grads = None
            
    def update_params(self, lr):
        for param in self.params:
            param.variable.data -= lr * param.variable.grads
            param.variable.grads = None
            
    def profile(self):
        times = {}
        for op in self.operations:
            if op.func.__name__ not in times:
                times[op.func.__name__] = 0.0
                
            times[op.func.__name__] += op.end_time - op.start_time
            
        total_time = sum(times.values())
        for func_name, time in times.items():
            print(f"{func_name}: {time/total_time:.2%}")
```

