class BinaryCrossEntropy:
    def __init__(self):
        pass
        
    def __repr__(self):
        return f"BinaryCrossEntropy()"
        
    def __call__(self, y_pred, y_true):
        return -np.mean(y_true * np.log(y_pred) + (1 - y_true) * np.log(1 - y_pred))
        
    def backward(self, y_pred, y_true):
        return - (y_true / y_pred - (1 - y_true) / (1 - y_pred)) / len(y_pred)
        
class LogisticRegression(LazyNN):
    def __init__(self, in_features):
        super().__init__()
        self.linear = Linear(in_features, 1)
        self.sigmoid = Sigmoid()
        
        self.add_parameter(self.linear)
        
    def construct_graph(self, x):
        linear_op = self.lazy_eval(x, np.dot, self.linear.variable.data)
        sigmoid_op = self.lazy_eval(linear_op.output, self.sigmoid)
        return sigmoid_op
        
    def fit(self, X, y, lr=0.1, epochs=100):
        for epoch in range(epochs):
            self.zero_grad()
            y_pred = self.forward(X)
            loss = BinaryCrossEntropy()(y_pred, y)
            self.backward(BinaryCrossEntropy().backward(y_pred, y))
            self.update_params(lr)
            
            if epoch % 10 == 0:
                print(f"Epoch {epoch}: loss={loss:.4f}")
                
        self.profile()
