class MultidimensionalArrayTransformer:
    def __init__(self, delimiter=','):
        self.delimiter = delimiter

    def transform(self, arr):
        if not isinstance(arr, list) or not arr:
            raise ValueError("Input must be a non-empty list")

        result = []
        self._recursive_transform(arr, result)

        return self.delimiter.join(result)

    def _recursive_transform(self, arr, result):
        for item in arr:
            if isinstance(item, list):
                self._recursive_transform(item, result)
            elif isinstance(item, int):
                result.append(str(item))
            else:
                raise ValueError("Only integers are allowed in the array")

    def to_json(self, arr):
        import json
        return json.dumps(arr)

    def to_xml(self, arr):
        from xml.etree import ElementTree as ET

        def _recursive_to_xml(arr, parent):
            for item in arr:
                if isinstance(item, list):
                    _recursive_to_xml(item, parent)
                elif isinstance(item, int):
                    item_element = ET.SubElement(parent, 'item')
                    item_element.text = str(item)
                else:
                    raise ValueError("Only integers are allowed in the array")

        root = ET.Element('root')
        _recursive_to_xml(arr, root)

        return ET.tostring(root, encoding='unicode')

