import queue

def get_moves_to_target(start_pos, target_pos):
    visited = set()
    q = queue.Queue()
    q.put((start_pos, []))

    while not q.empty():
        pos, path = q.get()

        if pos == target_pos:
            return path

        if pos not in visited:
            visited.add(pos)
            for move in get_possible_moves(pos):
                q.put((move, path + [move]))

    return None
