Here is an implementation of the BST class in Python:

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, value):
        self.root = self._insert_recursive(self.root, value)

    def _insert_recursive(self, node, value):
        if node is None:
            return Node(value)
        if value < node.value:
            node.left = self._insert_recursive(node.left, value)
        elif value > node.value:
            node.right = self._insert_recursive(node.right, value)
        return node

    def delete(self, value):
        self.root = self._delete_recursive(self.root, value)

    def _delete_recursive(self, node, value):
        if node is None:
            return node
        if value < node.value:
            node.left = self._delete_recursive(node.left, value)
        elif value > node.value:
            node.right = self._delete_recursive(node.right, value)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left
            else:
                temp = self._find_min(node.right)
                node.value = temp.value
                node.right = self._delete_recursive(node.right, temp.value)
        return node

    def search(self, value):
        return self._search_recursive(self.root, value)

    def _search_recursive(self, node, value):
        if node is None or node.value == value:
            return node
        if value < node.value:
            return self._search_recursive(node.left, value)
        return self._search_recursive(node.right, value)

    def find_min(self):
        if self.root is None:
            return None
        return self._find_min(self.root).value

    def _find_min(self, node):
        if node.left is None:
            return node
        return self._find_min(node.left)

    def find_max(self):
        if self.root is None:
            return None
        return self._find_max(self.root).value

    def _find_max(self, node):
        if node.right is None:
            return node
        return self._find_max(node.right)

    def find_kth_smallest(self, k):
        count = [0]
        return self._find_kth_smallest_recursive(self.root, k, count)

    def _find_kth_smallest_recursive(self, node, k, count):
        if node is None:
            return None
        left = self._find_kth_smallest_recursive(node.left, k, count)
        if left is not None:
            return left
        count[0] += 1
        if count[0] == k:
            return node.value
        return self._find_kth_smallest_recursive(node.right, k, count)

    def get_height(self):
        return self._get_height_recursive(self.root)

    def _get_height_recursive(self, node):
        if node is None:
            return 0
        return 1 + max(self._get_height_recursive(node.left), self._get_height_recursive(node.right))

    def is_balanced(self):
        return self._is_balanced_recursive(self.root)

    def _is_balanced_recursive(self, node):
        if node is None:
            return True
        left_height = self._get_height_recursive(node.left)
        right_height = self._get_height_recursive(node.right)
        if abs(left_height - right_height) > 1:
            return False
        return self._is_balanced_recursive(node.left) and self._is_balanced_recursive(node.right)

    def find_least_common_ancestor(self, node1, node2):
        return self._find_least_common_ancestor_recursive(self.root, node1, node2)

    def _find_least_common_ancestor_recursive(self, node, node1, node2):
        if node is None:
            return None
        if node.value > node1.value and node.value > node2.value:
            return self._find_least_common_ancestor_recursive(node.left, node1, node2)
        if node.value < node1.value and node.value < node2.value:
            return self._find_least_common_ancestor_recursive(node.right, node1, node2)
        return node.value

    def print_level_order(self):
        if self.root is None:
            return
        queue = [self.root]
        while queue:
            node = queue.pop(0)
            print(node.value, end=' ')
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

