Python code for Johnson's algorithm, which can solve the shortest path problem in graphs that have negative edge weights:

```python
import sys
from collections import defaultdict

class Graph:

    def __init__(self, vertices):
        self.V = vertices
        self.graph = defaultdict(list)

    def add_edge(self, u, v, w):
        self.graph[u].append((v, w))

    def bellman_ford(self, src):
        dist = [float("Inf")] * self.V
        dist[src] = 0

        for _ in range(self.V - 1):
            for u, v, w in self.edges:
                if dist[u] != float("Inf") and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

        for u, v, w in self.edges:
            if dist[u] != float("Inf") and dist[u] + w < dist[v]:
                return "Graph contains negative weight cycle"

        return dist

    def dijkstra(self, src):
        dist = [float("Inf")] * self.V
        dist[src] = 0
        visited = [False] * self.V

        for _ in range(self.V):
            min_dist = float("Inf")
            min_idx = None

            for v in range(self.V):
                if not visited[v] and dist[v] < min_dist:
                    min_dist = dist[v]
                    min_idx = v

            visited[min_idx] = True

            for v, w in self.graph[min_idx]:
                if not visited[v] and dist[min_idx] + w < dist[v]:
                    dist[v] = dist[min_idx] + w

        return dist

    def johnsons(self):
        self.graph[-1] = [(v, 0) for v in range(self.V)]
        self.edges = [(u, v, w) for u in self.graph for v, w in self.graph[u]]

        dist = self.bellman_ford(-1)
        if dist == "Graph contains negative weight cycle":
            return dist

        self.graph.pop(-1)

        for u in self.graph:
            for i in range(len(self.graph[u])):
                v, w = self.graph[u][i]
                self.graph[u][i] = (v, w + dist[u] - dist[v])

        res = [[0 for _ in range(self.V)] for _ in range(self.V)]
        for u in range(self.V):
            dist = self.dijkstra(u)
            for v in range(self.V):
                res[u][v] = dist[v] - dist[u] + dist[v]

        return res

g = Graph(4)
g.add_edge(0, 1, 1)
g.add_edge(0, 2, 4)
g.add_edge(1, 2, -3)
g.add_edge(2, 3, 2)

result = g.johnsons()
print(result)
```

This code defines a `Graph` class, which contains methods for adding edges, running Bellman-Ford and Dijkstra's algorithms, and running Johnson's algorithm to solve the shortest path problem in graphs with negative edge weights.

To run the code, create an instance of the `Graph` class, add edges using the `add_edge` method, and then call the `johnsons` method to get the shortest path distances.

