import threading
from typing import Any


class HashTable:
    def __init__(self, initial_size: int = 10, load_factor: float = 0.7):
        self.size = initial_size
        self.load_factor = load_factor
        self.current_size = 0
        self.keys = [None] * self.size
        self.values = [None] * self.size
        self.lock = threading.Lock()

    def hash_function(self, key: Any) -> int:
        # Custom hash function implementation
        if isinstance(key, int):
            return key % self.size
        elif isinstance(key, str):
            return sum(ord(c) for c in key) % self.size
        else:
            raise ValueError("Unsupported key type")

    def resize(self):
        self.size *= 2
        new_keys = [None] * self.size
        new_values = [None] * self.size

        for i in range(len(self.keys)):
            if self.keys[i] is not None:
                index = self.hash_function(self.keys[i])
                while new_keys[index] is not None:
                    index = (index + 1) % self.size
                new_keys[index] = self.keys[i]
                new_values[index] = self.values[i]

        self.keys = new_keys
        self.values = new_values

    def insert(self, key: Any, value: Any) -> None:
        with self.lock:
            if self.current_size / self.size >= self.load_factor:
                self.resize()

            index = self.hash_function(key)
            while self.keys[index] is not None:
                if self.keys[index] == key:
                    self.values[index] = value
                    return
                index = (index + 1) % self.size

            self.keys[index] = key
            self.values[index] = value
            self.current_size += 1

    def search(self, key: Any) -> Any:
        with self.lock:
            index = self.hash_function(key)
            while self.keys[index] is not None:
                if self.keys[index] == key:
                    return self.values[index]
                index = (index + 1) % self.size
            return None

    def delete(self, key: Any) -> None:
        with self.lock:
            index = self.hash_function(key)
            while self.keys[index] is not None:
                if self.keys[index] == key:
                    self.keys[index] = None
                    self.values[index] = None
                    self.current_size -= 1
                    return
                index = (index + 1) % self.size

    def print_table(self):
        for i in range(len(self.keys)):
            if self.keys[i] is not None:
                print(f"{self.keys[i]}: {self.values[i]}")
