import requests
import json
from datetime import datetime, timedelta
from threading import Lock


class APIWrapper:
    def __init__(self):
        self.base_url = 'https://api.example.com/'
        self.cache = {}
        self.cache_expiry = timedelta(minutes=5)
        self.lock = Lock()

    def _get_cached_response(self, key):
        if key in self.cache:
            cached_data, cached_time = self.cache[key]
            if datetime.now() - cached_time < self.cache_expiry:
                return cached_data
        return None

    def _cache_response(self, key, data):
        with self.lock:
            self.cache[key] = (data, datetime.now())

    def _make_api_call(self, endpoint, params=None, method='GET', data=None):
        url = self.base_url + endpoint
        headers = {'Content-Type': 'application/json'}
        try:
            if method == 'GET':
                response = requests.get(url, params=params, headers=headers)
            elif method == 'POST':
                response = requests.post(url, json=data, headers=headers)
            elif method == 'PUT':
                response = requests.put(url, json=data, headers=headers)
            elif method == 'DELETE':
                response = requests.delete(url, headers=headers)
            else:
                raise ValueError('Invalid HTTP method.')

            response.raise_for_status()
            return response.json()

        except requests.exceptions.RequestException as e:
            raise Exception('API call failed: {}'.format(str(e)))

    def get_all_users(self):
        cache_key = 'get_all_users'
        cached_response = self._get_cached_response(cache_key)
        if cached_response:
            return cached_response

        try:
            response = self._make_api_call('users')
            self._cache_response(cache_key, response)
            return response

        except Exception as e:
            return {'error': str(e)}

    def get_user_details(self, user_id):
        cache_key = 'get_user_details_{}'.format(user_id)
        cached_response = self._get_cached_response(cache_key)
        if cached_response:
            return cached_response

        try:
            response = self._make_api_call('users/{}'.format(user_id))
            self._cache_response(cache_key, response)
            return response

        except Exception as e:
            return {'error': str(e)}

    def create_user(self, user_data):
        try:
            response = self._make_api_call('users', method='POST', data=user_data)
            self._clear_cache()
            return response

        except Exception as e:
            return {'error': str(e)}

    def update_user(self, user_id, user_data):
        try:
            response = self._make_api_call('users/{}'.format(user_id), method='PUT', data=user_data)
            self._clear_cache()
            return response

        except Exception as e:
            return {'error': str(e)}

    def delete_user(self, user_id):
        try:
            response = self._make_api_call('users/{}'.format(user_id), method='DELETE')
            self._clear_cache()
            return response

        except Exception as e:
            return {'error': str(e)}

    def _clear_cache(self):
        with self.lock:
            self.cache = {}


