import socket
import struct

def validate_ip_address(ip_address):
    try:
        socket.inet_pton(socket.AF_INET, ip_address)
        return True
    except socket.error:
        try:
            socket.inet_pton(socket.AF_INET6, ip_address)
            return True
        except socket.error:
            return False

def get_ip_class(ip_address):
    if ip_address.startswith('127.'):
        return 'Loopback IP Address'
    elif ip_address.startswith('169.254.'):
        return 'Link-local IP Address'
    elif ip_address.startswith('239.'):
        return 'Multicast IP Address'
    elif ip_address.startswith('10.') or ip_address.startswith('172.16.') or ip_address.startswith('192.168.'):
        return 'Private IP Address'
    elif ip_address.startswith('0.') or ip_address.startswith('100.64.') or ip_address.startswith('127.') or ip_address.startswith('169.254.') or ip_address.startswith('192.0.0.') or ip_address.startswith('192.0.2.') or ip_address.startswith('198.18.') or ip_address.startswith('198.19.') or ip_address.startswith('203.0.113.') or ip_address.startswith('240.') or ip_address.startswith('255.255.255.255'):
        return 'Reserved IP Address'
    else:
        return 'Public IP Address'

def get_subnet_mask(ip_address, subnet_mask):
    if subnet_mask.startswith('/'):
        try:
            cidr = int(subnet_mask[1:])
            if ip_address.count('.') == 3:
                subnet_mask = socket.inet_ntoa(struct.pack('!I', (0xffffffff << (32 - cidr)) & 0xffffffff))
            else:
                subnet_mask = socket.inet_ntop(socket.AF_INET6, struct.pack('!I', (0xffffffff << (128 - cidr)) & 0xffffffffffffffffffffffffffffffff))
        except ValueError:
            return 'Invalid Subnet Mask'
    elif not validate_ip_address(subnet_mask):
        return 'Invalid Subnet Mask'

    return subnet_mask

def get_default_gateways(ip_address, default_gateways):
    gateways = []
    for gateway in default_gateways:
        if validate_ip_address(gateway):
            gateways.append(gateway)
        else:
            return 'Invalid Default Gateway'
    return gateways

def analyze_ip_address(ip_address, subnet_mask=None, default_gateways=None):
    if not validate_ip_address(ip_address):
        return 'Invalid IP Address'

    ip_class = get_ip_class(ip_address)
    subnet_mask = get_subnet_mask(ip_address, subnet_mask) if subnet_mask else None
    default_gateways = get_default_gateways(ip_address, default_gateways) if default_gateways else None

    return {
        'IP Address': ip_address,
        'IP Class': ip_class,
        'Subnet Mask': subnet_mask,
        'Default Gateways': default_gateways
    }

