import csv
import json

def validate_json(json_data):
    required_fields = ["name", "age", "job", "address", "education", "experience"]
    for field in required_fields:
        if field not in json_data:
            raise ValueError(f"Missing required field: {field}")

def extract_nested_fields(json_data, prefix='', fields=None):
    if fields is None:
        fields = {}
    if isinstance(json_data, dict):
        for key, value in json_data.items():
            if isinstance(value, (dict, list)):
                extract_nested_fields(value, prefix=f"{prefix}{key}_", fields=fields)
            else:
                fields[f"{prefix}{key}"] = value
    elif isinstance(json_data, list):
        for index, item in enumerate(json_data):
            extract_nested_fields(item, prefix=f"{prefix}{index+1}_", fields=fields)
    return fields

def json_to_csv(json_data):
    validate_json(json_data)
    fields = extract_nested_fields(json_data)
    fieldnames = list(fields.keys())
    with open('output.csv', 'w', newline='') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerow(fields)

