class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None

class Hashmap:
    def __init__(self, initial_capacity=16, load_factor=0.75):
        self.capacity = initial_capacity
        self.load_factor = load_factor
        self.size = 0
        self.buckets = [None] * self.capacity

    def hash(self, key):
        return hash(key) % self.capacity

    def resize(self):
        new_capacity = self.capacity * 2
        new_buckets = [None] * new_capacity

        for node in self.buckets:
            while node:
                new_hash = self.hash(node.key)
                if new_buckets[new_hash] is None:
                    new_buckets[new_hash] = Node(node.key, node.value)
                else:
                    new_node = new_buckets[new_hash]
                    while new_node.next:
                        new_node = new_node.next
                    new_node.next = Node(node.key, node.value)
                node = node.next

        self.capacity = new_capacity
        self.buckets = new_buckets

    def put(self, key, value):
        hash_val = self.hash(key)
        if self.buckets[hash_val] is None:
            self.buckets[hash_val] = Node(key, value)
        else:
            node = self.buckets[hash_val]
            while node.next:
                if node.key == key:
                    node.value = value
                    return
                node = node.next
            if node.key == key:
                node.value = value
            else:
                node.next = Node(key, value)

        self.size += 1

        if self.size > self.load_factor * self.capacity:
            self.resize()

    def get(self, key):
        hash_val = self.hash(key)
        node = self.buckets[hash_val]
        while node:
            if node.key == key:
                return node.value
            node = node.next
        return None

    def delete(self, key):
        hash_val = self.hash(key)
        node = self.buckets[hash_val]
        prev = None

        while node:
            if node.key == key:
                if prev:
                    prev.next = node.next
                else:
                    self.buckets[hash_val] = node.next
                self.size -= 1
                return True
            prev = node
            node = node.next

        return False

    def get_keys(self):
        keys = []
        for node in self.buckets:
            while node:
                keys.append(node.key)
                node = node.next
        return keys

    def get_values(self):
        values = []
        for node in self.buckets:
            while node:
                values.append(node.value)
                node = node.next
        return values

    def contains_key(self, key):
        hash_val = self.hash(key)
        node = self.buckets[hash_val]
        while node:
            if node.key == key:
                return True
            node = node.next
        return False

    def contains_value(self, value):
        for node in self.buckets:
            while node:
                if node.value == value:
                    return True
                node = node.next
        return False

    def clear(self):
        self.size = 0
        self.buckets = [None] * self.capacity
