        if self.stack:
            return self.stack[-1]
        else:
            return None

    def is_empty(self):
        return len(self.stack) == 0

    def size(self):
        return len(self.stack)

    def get_min(self):
        if self.min_stack:
            return self.min_stack[-1]
        else:
            return None

    def peek_min(self):
        return self.get_min()


