        self.balance += amount
        self.transaction_history.append((datetime.datetime.now(), 'Deposit', amount))

    def withdraw(self, amount):
        if self.balance >= amount:
            self.balance -= amount
            self.transaction_history.append((datetime.datetime.now(), 'Withdrawal', amount))
        else:
            print("Insufficient funds.")

    def check_balance(self):
        return self.balance

    def apply_interest(self, rate):
        interest = self.balance * rate
        self.balance += interest
        self.transaction_history.append((datetime.datetime.now(), 'Interest', interest))

    def transfer(self, amount, recipient_account):
        if self.balance >= amount:
            self.balance -= amount
            recipient_account.deposit(amount)
            self.transaction_history.append((datetime.datetime.now(), 'Transfer', amount))
        else:
            print("Insufficient funds.")

    def authenticate_user(self, username, password):
        # Authenticate user logic here
        self.authenticated_users.add(username)

    def track_transaction_history(self):
        for transaction in self.transaction_history:
            print(transaction)

